-- Helpful indexes for the admin dashboard and same-day active-order lookup
CREATE INDEX idx_orders_restaurant_created_at ON orders(restaurant_id, created_at);
CREATE INDEX idx_orders_customer_lookup ON orders(restaurant_id, customer_phone, customer_name, order_type, table_number, status, created_at);
CREATE INDEX idx_menu_items_restaurant_food_type ON menu_items(restaurant_id, food_type, is_available);

-- Auto-update updated_at timestamps
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER restaurants_updated_at BEFORE UPDATE ON restaurants FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER users_updated_at BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER menu_items_updated_at BEFORE UPDATE ON menu_items FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER orders_updated_at BEFORE UPDATE ON orders FOR EACH ROW EXECUTE FUNCTION set_updated_at();